Item.method_code:
var controlId = this.getID();
var controlName = this.getProperty("name");

if (string.IsNullOrEmpty(controlName))
{
	var cuiControl = this.newItem("cui_Control", "get");
	cuiControl.setID(controlId);
	cuiControl.setAttribute("select", "name");
	var cuiControlResult = cuiControl.apply();
	if (cuiControlResult.isError())
	{
		return cuiControlResult;
	}

	controlName = cuiControlResult.getProperty("name");
}

this.setProperty("keyed_name", $"{controlName}_{controlId}");
return this;
